export type CreatePromotionRequest = { "application_method": PromotionApplicationMethod; "combines_with"?: PromotionCombinesWith; "description"?: string; /** Defaults to order when omitted. */ "discount_class"?: "order" | "line_item" | "service_charge" | (string & {}); /** Buyer-facing promotion name shown in checkout and order discount surfaces. Defaults to name when omitted. */ "display_name"?: string; /** A rule group is exactly one of three forms, never a blend: an array of rules for a simple list (an implicit AND), an object with only all for nested AND, or an object with only any for OR. The all and any arrays contain rules or nested rule groups. There is no rules key. Sending a rules key, an unexpected key, or both all and any is rejected with INVALID_RULE_GROUP. */ "eligibility_rules"?: ((Array<PromotionRule>) | ({ "all": Array<(({ /** Field the rule tests. The attribute fixes the value type and the operators that are legal for it: money attributes accept comparison operators but not eq or in, booleans accept eq only, and so on. The full attribute/type/operator matrix is machine-readable in x-flint-rule-attributes on this schema. metadata.<key> reads a string from the customer's metadata and accepts the string operators. A disallowed operator is rejected at create time with INVALID_OPERATOR, whose message names the operators allowed for the attribute. */ "attribute": string; "currency_options"?: Record<string, MoneyValue>; "operator": "eq" | "ne" | "gt" | "gte" | "lt" | "lte" | "in" | "contains" | "is_defined" | (string & {}); "values"?: Array<PromotionRuleValue>; }) | (PromotionRuleGroup) | (unknown))>; }) | ({ "any": Array<(({ /** Field the rule tests. The attribute fixes the value type and the operators that are legal for it: money attributes accept comparison operators but not eq or in, booleans accept eq only, and so on. The full attribute/type/operator matrix is machine-readable in x-flint-rule-attributes on this schema. metadata.<key> reads a string from the customer's metadata and accepts the string operators. A disallowed operator is rejected at create time with INVALID_OPERATOR, whose message names the operators allowed for the attribute. */ "attribute": string; "currency_options"?: Record<string, MoneyValue>; "operator": "eq" | "ne" | "gt" | "gte" | "lt" | "lte" | "in" | "contains" | "is_defined" | (string & {}); "values"?: Array<PromotionRuleValue>; }) | (PromotionRuleGroup) | (unknown))>; }) | (unknown)); "exclusivity"?: PromotionExclusivity; /** Caller-owned identifier for this resource in an external system. minLength: 1. maxLength: 255. */ "external_reference_id"?: string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "max_uses"?: string; "metadata"?: Record<string, string>; /** Internal promotion name for dashboards, searching, and reporting. This is not intended for buyer-facing checkout or receipt copy. */ "name": string; "redemption_type"?: "automatic" | "code" | (string & {}); "schedule"?: PromotionSchedule; "stacking_mode"?: "continue" | "stop_after" | (string & {}); };
